// AxiosConfig.js
import axios from "axios";
import store from "../redux/store";
import { logout, updateToken } from "./";

const instance = axios.create({
  baseURL: process.env.REACT_APP_SERVER_URL,
  withCredentials: true, // Quan trọng: cho phép gửi cookies (refresh token)
});

// === Request Interceptor ===
instance.interceptors.request.use(
  function (config) {
    const tokenRaw = window.localStorage.getItem("persist:auth");
    let token = null;
    if (tokenRaw) {
      try {
        const parsed = JSON.parse(tokenRaw);
        const userData = parsed.user ? JSON.parse(parsed.user) : null;
        token = userData?.token;
      } catch (err) {
        console.error("Error parsing token from localStorage:", err);
      }
    }

    if (token) {
      config.headers["Authorization"] = `Bearer ${token}`;
    }

    return config;
  },
  function (error) {
    return Promise.reject(error);
  }
);

// === Response Interceptor ===
let isRefreshing = false;
let failedQueue = [];

const processQueue = (error, token = null) => {
  failedQueue.forEach((prom) => {
    if (error) {
      prom.reject(error);
    } else {
      prom.resolve(token);
    }
  });
  failedQueue = [];
};

instance.interceptors.response.use(
  (response) => response,
  async (error) => {
    const originalRequest = error.config;

    if (error.response?.status === 401 && !originalRequest._retry) {
      originalRequest._retry = true;

      if (isRefreshing) {
        return new Promise((resolve, reject) => {
          failedQueue.push({ resolve, reject });
        }).then((token) => {
          originalRequest.headers["Authorization"] = `Bearer ${token}`;
          return instance(originalRequest);
        });
      }

      isRefreshing = true;
      try {
        const res = await axios.post(
          `${process.env.REACT_APP_SERVER_URL}/auth/refresh-token`,
          {},
          { withCredentials: true }
        );
        const newToken = res.data.token;

        // Cập nhật Redux + localStorage
        store.dispatch(updateToken(newToken));

        const authRaw = localStorage.getItem("persist:auth");
        if (authRaw) {
          const parsed = JSON.parse(authRaw);
          const userData = parsed.user ? JSON.parse(parsed.user) : {};
          userData.token = newToken;
          parsed.user = JSON.stringify(userData);
          localStorage.setItem("persist:auth", JSON.stringify(parsed));
        }

        processQueue(null, newToken);
        originalRequest.headers["Authorization"] = `Bearer ${newToken}`;
        return instance(originalRequest);
      } catch (refreshError) {
        processQueue(refreshError, null);
        store.dispatch(logout());
        window.location.href = "/login";
        return Promise.reject(refreshError);
      } finally {
        isRefreshing = false;
      }
    }

    return Promise.reject(error);
  }
);

export default instance;
